]$catalog_data$;
  scholarship jsonb;
  provider jsonb;
  source_data jsonb;
  department jsonb;
  requirement jsonb;
  new_scholarship_id integer;
  provider_id_for_row integer;
  source_id_for_row integer;
  requirement_id_for_row integer;
BEGIN
  FOR scholarship IN SELECT value FROM jsonb_array_elements(catalog)
  LOOP
    -- Reserve the slug first so an existing record never has its links modified.
    INSERT INTO scholarships (
      title, slug, type, coverage, description, official_url, application_url,
      opening_date, closing_date, status, continents, needs_review, updated_at
    ) VALUES (
      scholarship->>'title', scholarship->>'slug',
      (scholarship->>'type')::"ScholarshipType", (scholarship->>'coverage')::"Coverage",
      scholarship->>'description', scholarship->>'official_url', scholarship->>'application_url',
      (scholarship->>'opening_date')::timestamp, (scholarship->>'closing_date')::timestamp,
      (scholarship->>'status')::"ScholarshipStatus",
      ARRAY(SELECT jsonb_array_elements_text(scholarship->'continents')),
      false, CURRENT_TIMESTAMP AT TIME ZONE 'UTC'
    )
    ON CONFLICT (slug) DO NOTHING
    RETURNING id INTO new_scholarship_id;

    IF NOT FOUND THEN
      CONTINUE;
    END IF;

    provider := scholarship->'provider';
    provider_id_for_row := NULL;
    IF jsonb_typeof(provider) = 'object' THEN
      SELECT id INTO provider_id_for_row FROM entities
      WHERE name = provider->>'name'
        AND type = (provider->>'type')::"EntityType"
        AND acronym IS NOT DISTINCT FROM (provider->>'acronym')
        AND website IS NOT DISTINCT FROM (provider->>'website')
      ORDER BY id LIMIT 1;
      IF NOT FOUND THEN
        INSERT INTO entities (name, type, acronym, website)
        VALUES (provider->>'name', (provider->>'type')::"EntityType",
                provider->>'acronym', provider->>'website')
        RETURNING id INTO provider_id_for_row;
      END IF;
    END IF;

    source_data := scholarship->'source';
    source_id_for_row := NULL;
    IF jsonb_typeof(source_data) = 'object' THEN
      INSERT INTO sources (name, type, active)
      VALUES (source_data->>'name', (source_data->>'type')::"SourceType", false)
      ON CONFLICT (name) DO NOTHING;
      SELECT id INTO source_id_for_row FROM sources WHERE name = source_data->>'name';
    END IF;

    UPDATE scholarships
    SET provider_id = provider_id_for_row, source_id = source_id_for_row
    WHERE id = new_scholarship_id;

    FOR department IN SELECT value FROM jsonb_array_elements(scholarship->'departments')
    LOOP
      INSERT INTO departments (name, dane_code)
      VALUES (department->>'name', department->>'dane_code')
      ON CONFLICT DO NOTHING;
      INSERT INTO scholarship_departments (scholarship_id, department_id)
      VALUES (new_scholarship_id, (
        SELECT id FROM departments
        WHERE dane_code = department->>'dane_code' OR name = department->>'name'
        ORDER BY (dane_code = department->>'dane_code') DESC LIMIT 1
      ))
      ON CONFLICT DO NOTHING;
    END LOOP;

    FOR requirement IN SELECT value FROM jsonb_array_elements(scholarship->'requirements')
    LOOP
      SELECT id INTO requirement_id_for_row FROM requirements
      WHERE type = (requirement->>'type')::"RequirementType"
        AND label = requirement->>'label' AND value = requirement->'value'
      ORDER BY id LIMIT 1;
      IF NOT FOUND THEN
        INSERT INTO requirements (type, label, value)
        VALUES ((requirement->>'type')::"RequirementType", requirement->>'label', requirement->'value')
        RETURNING id INTO requirement_id_for_row;
      END IF;
      INSERT INTO scholarship_requirements (scholarship_id, requirement_id)
      VALUES (new_scholarship_id, requirement_id_for_row)
      ON CONFLICT DO NOTHING;
    END LOOP;
  END LOOP;
END;
$load_catalog$;

COMMIT;
